//! Fixture parity tests for the ACE-Step 1.5 condition encoder, DiT and
//! turbo sampler.
//!
//! Tiny fixtures live in `testdata/ace_step15_dit/`, regenerated by
//! `tools/gen_ace_step15_dit_fixtures.py` from the checkpoint's own
//! modeling code on the CPU in f32 (weights stored in bf16). The
//! real-checkpoint test is ignored: point TURBOSPARK_ACE_STEP15_DIT at
//! the `acestep-v15-turbo/` directory and TURBOSPARK_ACE_STEP15_DIT_REF
//! at the `--real` output directory. Tests never download.

use std::path::{Path, PathBuf};

use super::dit::{
    cover_switch_step, sample_turbo, turbo_schedule, ConditionEncoder, Conditioning, Dit,
    StepCondition,
};
use super::tests::{read_npy, rel_err};
use super::tokenizer::{cover_hints, AudioDetokenizer, AudioTokenizer};
use super::transformer::{window_mask, AceConfig, Loader};
use turbospark_model_io::safetensors::SafetensorsFile;

fn testdata(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("testdata/ace_step15_dit")
        .join(name)
}

fn npy(dir: &Path, name: &str) -> (Vec<usize>, Vec<f32>) {
    read_npy(&dir.join(format!("{name}.npy")))
}

/// Interleaves `[frames, a]` source latents and chunk masks into the
/// `[frames, 2a]` context the DiT takes.
fn context(src: &[f32], chunk: &[f32], frames: usize, a: usize) -> Vec<f32> {
    let mut ctx = Vec::with_capacity(frames * 2 * a);
    for f in 0..frames {
        ctx.extend_from_slice(&src[f * a..(f + 1) * a]);
        ctx.extend_from_slice(&chunk[f * a..(f + 1) * a]);
    }
    ctx
}

/// Runs every stage against the arrays in `dir` and returns each
/// stage's relative error. Each stage is fed the reference output of the
/// stage before it, so a failure points at one module. FSQ indices must
/// match exactly; the count of mismatches is returned as `indices`.
fn check(
    config: &AceConfig,
    file: &SafetensorsFile,
    dir: &Path,
    t_step: f32,
) -> Vec<(&'static str, f32)> {
    let l = Loader::cpu(file);
    let enc_model = ConditionEncoder::load(&l, config).unwrap();
    let dit = Dit::load(&l, config).unwrap();
    let tokenizer = AudioTokenizer::load(&l, config).unwrap();
    let detokenizer = AudioDetokenizer::load(&l, config).unwrap();
    let a = config.audio_acoustic_hidden_dim;
    let (ls, lyric) = npy(dir, "lyric");
    let (rs, refer) = npy(dir, "refer");
    let encode = |name: &str| {
        let (ts, text) = npy(dir, name);
        enc_model
            .forward(&Conditioning {
                text: &text,
                text_len: ts[0],
                lyric: &lyric,
                lyric_len: ls[0],
                refer: &refer,
                refer_len: rs[0],
            })
            .unwrap()
    };
    let mut out = Vec::new();
    let (enc, enc_seq) = encode("text");
    let (es, want_enc) = npy(dir, "encoder");
    assert_eq!(enc_seq, es[0]);
    out.push(("encoder", rel_err(&enc, &want_enc)));
    let (enc_nc, _) = encode("text_nc");
    let (ns, want_enc_nc) = npy(dir, "encoder_nc");
    out.push(("encoder_nc", rel_err(&enc_nc, &want_enc_nc)));

    let embedded = dit.embed_condition(&want_enc, es[0]).unwrap();
    let (xs, x) = npy(dir, "x");
    let frames = xs[0];
    let (_, ctx_in) = npy(dir, "context");
    let v = dit
        .forward(&x, &ctx_in, frames, t_step, &embedded, es[0])
        .unwrap();
    out.push(("velocity", rel_err(&v, &npy(dir, "velocity").1)));

    let (_, src) = npy(dir, "src");
    let (_, chunk) = npy(dir, "chunk");
    let (_, noise) = npy(dir, "noise");
    let schedule = turbo_schedule(3.0);
    let plain = context(&src, &chunk, frames, a);
    let primary = StepCondition {
        context: &plain,
        enc: &embedded,
        enc_seq: es[0],
    };
    let latents = sample_turbo(&dit, &noise, frames, &schedule, primary, None, None, |_| {
        true
    })
    .unwrap()
    .unwrap();
    out.push(("latents", rel_err(&latents, &npy(dir, "latents").1)));

    let (_, silence) = npy(dir, "silence");
    let (tokens, indices) = tokenizer.tokenize(&src, frames, &silence).unwrap();
    out.push(("tokens", rel_err(&tokens, &npy(dir, "tokens").1)));
    let want_idx = super::text_tests::read_i32(&dir.join("indices.npy"));
    assert_eq!(indices.len(), want_idx.len(), "token count");
    let mismatched = indices
        .iter()
        .zip(&want_idx)
        .filter(|(a, b)| a != b)
        .count();
    out.push(("indices", mismatched as f32));
    let (_, want_tokens) = npy(dir, "tokens");
    let windows = want_tokens.len() / config.hidden_size;
    let mut hints = detokenizer.detokenize(&want_tokens, windows).unwrap();
    hints.truncate(frames * a);
    let (_, want_hints) = npy(dir, "hints");
    out.push(("hints", rel_err(&hints, &want_hints)));
    let chained = cover_hints(&tokenizer, &detokenizer, &src, frames, &silence).unwrap();
    out.push(("hints_chained", rel_err(&chained, &want_hints)));

    let cover_ctx = context(&want_hints, &chunk, frames, a);
    let fallback_ctx = context(&silence[..frames * a], &chunk, frames, a);
    let embedded_nc = dit.embed_condition(&want_enc_nc, ns[0]).unwrap();
    let switch = cover_switch_step(schedule.len(), 0.5).unwrap();
    let cover = sample_turbo(
        &dit,
        &noise,
        frames,
        &schedule,
        StepCondition {
            context: &cover_ctx,
            enc: &embedded,
            enc_seq: es[0],
        },
        Some((
            switch,
            StepCondition {
                context: &fallback_ctx,
                enc: &embedded_nc,
                enc_seq: ns[0],
            },
        )),
        None,
        |_| true,
    )
    .unwrap()
    .unwrap();
    out.push((
        "latents_cover",
        rel_err(&cover, &npy(dir, "latents_cover").1),
    ));
    out
}

fn report(tag: &str, errs: &[(&str, f32)], tol: f32) {
    let line: Vec<String> = errs.iter().map(|(n, e)| format!("{n} {e:.2e}")).collect();
    eprintln!("{tag}: {}", line.join(" "));
    for (stage, e) in errs {
        if *stage == "indices" {
            assert_eq!(*e, 0.0, "{tag}: {e} FSQ indices differ");
        } else {
            assert!(*e <= tol, "{tag} {stage}: relative error {e:.3e}");
        }
    }
}

fn tiny_config() -> AceConfig {
    let text = std::fs::read_to_string(testdata("tiny_config.json")).unwrap();
    AceConfig::from_json(&serde_json::from_str(&text).unwrap()).unwrap()
}

#[test]
fn window_mask_is_symmetric_band() {
    let m = window_mask(5, 1);
    let visible: Vec<Vec<usize>> = (0..5)
        .map(|i| (0..5).filter(|&j| m[i * 5 + j] == 0.0).collect())
        .collect();
    assert_eq!(
        visible,
        vec![
            vec![0, 1],
            vec![0, 1, 2],
            vec![1, 2, 3],
            vec![2, 3, 4],
            vec![3, 4]
        ]
    );
    assert!(m.iter().all(|&v| v == 0.0 || v == f32::MIN));
}

#[test]
fn schedule_rounds_to_trained_shift() {
    assert_eq!(turbo_schedule(3.0)[7], 0.3);
    assert_eq!(turbo_schedule(2.6), turbo_schedule(3.0));
    assert_eq!(turbo_schedule(1.2)[1], 0.875);
    assert_eq!(turbo_schedule(2.0)[7], 0.2222222222222222f64 as f32);
}

#[test]
fn shipped_config_parses() {
    let text = std::fs::read_to_string(testdata("tiny_config.json")).unwrap();
    let mut v: serde_json::Value = serde_json::from_str(&text).unwrap();
    v["in_channels"] = serde_json::json!(25);
    assert!(
        AceConfig::from_json(&v).is_err(),
        "in_channels must be 3 x acoustic"
    );
    let mut v: serde_json::Value = serde_json::from_str(&text).unwrap();
    v["layer_types"] = serde_json::json!(["full_attention"]);
    assert!(AceConfig::from_json(&v).is_err(), "too few layer_types");
    let mut v: serde_json::Value = serde_json::from_str(&text).unwrap();
    v["rope_scaling"] = serde_json::json!({"type": "linear", "factor": 2.0});
    assert!(AceConfig::from_json(&v).is_err(), "rope scaling is refused");
}

/// Measured on M4 Max: worst stage 2.5e-6 (velocity); tokens 5.4e-8,
/// hints 4.4e-7, cover latents 4.2e-7, FSQ indices exact. The bound keeps about 4x headroom over the worst stage.
/// Disabling the sliding mask, packing text first, embedding `t` instead
/// of `t - r`, gating the MLP with the attention gate, or rotating k
/// interleaved instead of half-split each fail it by 1e-2 or more; so do
/// dropping the FSQ soft clamp, padding from the silence tail, switching
/// cover one step late, rounding instead of flooring the FSQ bracket,
/// dropping the detokenizer offsets, or pooling the wrong row.
const TINY_TOL: f32 = 1e-5;

#[test]
fn tiny_matches_reference() {
    let config = tiny_config();
    let file = SafetensorsFile::open(&testdata("tiny_weights.safetensors")).unwrap();
    report(
        "tiny",
        &check(&config, &file, &testdata(""), 0.75),
        TINY_TOL,
    );
}

#[test]
fn dit_rejects_bad_shapes() {
    let config = tiny_config();
    let file = SafetensorsFile::open(&testdata("tiny_weights.safetensors")).unwrap();
    let dit = Dit::load(&Loader::cpu(&file), &config).unwrap();
    let a = config.audio_acoustic_hidden_dim;
    let d = config.hidden_size;
    assert!(dit
        .forward(
            &vec![0.0; 4 * a],
            &vec![0.0; 3 * 2 * a],
            4,
            0.5,
            &vec![0.0; d],
            1
        )
        .is_err());
    assert!(dit
        .forward(
            &vec![0.0; 4 * a],
            &vec![0.0; 4 * 2 * a],
            4,
            0.5,
            &vec![0.0; d - 1],
            1
        )
        .is_err());
    assert!(dit.forward(&[], &[], 0, 0.5, &vec![0.0; d], 1).is_err());
}

/// Real turbo checkpoint (bf16 widened to f32), 2 s of latents, 8 steps.
/// Measured on M4 Max: worst stage 7.3e-6 (text2music latents); FSQ
/// indices 10 of 10 exact, cover latents 6.1e-6. Bound keeps about 2.7x.
#[test]
#[ignore = "needs TURBOSPARK_ACE_STEP15_DIT and TURBOSPARK_ACE_STEP15_DIT_REF"]
fn real_checkpoint_matches_reference() {
    let (Ok(dit_dir), Ok(ref_dir)) = (
        std::env::var("TURBOSPARK_ACE_STEP15_DIT"),
        std::env::var("TURBOSPARK_ACE_STEP15_DIT_REF"),
    ) else {
        panic!("set TURBOSPARK_ACE_STEP15_DIT and TURBOSPARK_ACE_STEP15_DIT_REF");
    };
    let dit_dir = PathBuf::from(dit_dir);
    let text = std::fs::read_to_string(dit_dir.join("config.json")).unwrap();
    let config = AceConfig::from_json(&serde_json::from_str(&text).unwrap()).unwrap();
    let file = SafetensorsFile::open(&dit_dir.join("model.safetensors")).unwrap();
    report(
        "real",
        &check(&config, &file, Path::new(&ref_dir), 0.75),
        2e-5,
    );
}
